public ListNode? OddEvenTwoLists(ListNode? head)
{
    if (head == null) return null;
    ListNode oddHead = new ListNode(0);
    ListNode evenHead = new ListNode(0);
    ListNode oddTail = oddHead, evenTail = evenHead;
    bool isOdd = true;
    while (head != null)
    {
        if (isOdd) { oddTail.Next = new ListNode(head.Val); oddTail = oddTail.Next; }
        else { evenTail.Next = new ListNode(head.Val); evenTail = evenTail.Next; }
        head = head.Next; isOdd = !isOdd;
    }
    oddTail.Next = evenHead.Next;
    return oddHead.Next;
}

public ListNode? OddEvenList(ListNode? head)
{
    if (head == null) return null;
    ListNode odd = head, even = head.Next, evenHead = even;
    while (even != null && even.Next != null)
    {
        odd.Next = even.Next;
        odd = odd.Next;
        even.Next = odd.Next;
        even = even.Next;
    }
    odd.Next = evenHead;
    return head;
}
